    result = []
    window = []

    for i, num in enumerate(numbers):
        if window and i - window[0] >= len(window):
            window.pop(0)

        while window and numbers[window[-1]] < num:
            window.pop()

        window.append(i)

        if i >= len(window) - 1:
            result.append(numbers[window[0]])

